pub async fn prepare_dynfilter_variants(
    conn: &mut sqlx::SqliteConnection,
) -> Result<(), sqlx::Error> {
    self::prepare_list_users_by_scope(conn).await?;
    self::prepare_count_users_with_orders(conn).await?;
    self::prepare_search_users_with_orders(conn).await?;
    self::prepare_search_users_by_pattern(conn).await?;
    self::prepare_search_users_by_last_order(conn).await?;
    self::prepare_list_users_without_orders(conn).await?;
    self::prepare_list_users_having_alias(conn).await?;
    self::prepare_count_users_with_phoned_orders(conn).await?;
    self::prepare_count_phoned_users(conn).await?;
    Ok(())
}
